import React, { useState } from 'react'

const Signup = () => {
    const [credentials, setcredentials] = useState({ name:"",email: "", password: "" ,cpassword:""});
    const handlesubmit = async (e) => {
        e.preventDefault();
        const response = await fetch("http://localhost:5001/api/auth/createuser", {
            method: "POST",
            headers: {
                "Content-Type": "application/json",
            },
            body: JSON.stringify({name:credentials.name, email: credentials.email, password: credentials.password ,cpassword:credentials.cpassword}),
        });
        const json = await response.json();
        console.log(json);
        // if (json.success) {
        //     //Save the token and redirect
        //     localStorage.setItem("token", json.authtoken);
        //     history.push("/");
        // } else {
        //     alert("Wrong credentials")
        // }
    }
    const onChange = (e) => {
        setcredentials({ ...credentials, [e.target.name]: e.target.value });
    }
    return (
        <div>
            <form >
                <div className="mb-3">
                    <label htmlFor="name" className="form-label">Name</label>
                    <input type="text" className="form-control" id="name" name="name" aria-describedby="emailHe" onChange={onChange} style={{ width: "500px" }} />
                </div>
                <div className="mb-3">
                    <label htmlFor="email" className="form-label">Email address</label>
                    <input type="email" className="form-control" id="email" name="email" aria-describedby="emailHe" onChange={onChange} style={{ width: "500px" }} />
                </div>
                <div className="mb-3">
                    <label htmlFor="password" className="form-label">Password</label>
                    <input type="password" className="form-control" id="password" name="password" onChange={onChange} style={{ width: "500px" }} />
                </div>
                <div className="mb-3">
                    <label htmlFor="cpassword" className="form-label">Confirm Password</label>
                    <input type="password" className="form-control" onChange={onChange} id="cpassword" name="cpassword" style={{ width: "500px" }} />
                </div>
                <button type="submit" className="btn btn-info">Submit</button>
            </form>
        </div>
    )
}

export default Signup
